import { render, screen, userEvent } from '@testing-library/react-native';
import { HikeForm } from '../HikeForm';

test('shows an error, then saves once the distance is fixed', async () => {
  const onSave = jest.fn();
  const user = userEvent.{{0}}();
  await {{1}}(<HikeForm onSave={onSave} />);

  const distance = screen.getByLabelText('Distance (km)');
  await user.type(screen.getByLabelText('Name'), 'Ridge Loop');
  await user.type(distance, 'far');
  await user.{{2}}(screen.getByRole('{{3}}', { name: 'Save' }));

  expect(screen.getByText('Enter a distance in km, like 8.4.')).{{4}}();
  expect(onSave).not.toHaveBeenCalled();

  await user.clear(distance);
  await user.type(distance, '8,4');
  await user.press(screen.getByRole('button', { name: 'Save' }));

  expect(onSave).{{5}}(expect.objectContaining({ name: 'Ridge Loop', distanceKm: 8.4 }));
});
